<script setup>
import { computed,onMounted,ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import QrcodeVue from 'qrcode.vue'
import { getCheckoutOrder } from '@/services/checkoutService'
import { getOrderToken } from '@/utils/checkoutStorage'
const route=useRoute(),router=useRouter(),order=ref(null),loading=ref(true),error=ref('');const id=computed(()=>String(route.params.orderId||''));const token=computed(()=>getOrderToken(id.value));const paid=computed(()=>order.value?.status==='paid'),review=computed(()=>order.value?.status==='payment_review');const groups=computed(()=>{const map=new Map();for(const item of order.value?.items||[]){const key=String(item.event_id);if(!map.has(key))map.set(key,{event_title:item.event_title,items:[]});map.get(key).items.push(item)}return[...map.values()]});const load=async()=>{try{order.value=await getCheckoutOrder({orderId:id.value,checkoutToken:token.value})}catch{error.value='We could not load this order.'}finally{loading.value=false}};onMounted(load)
</script><template><main><section v-if="loading">Confirming your payment…</section><section v-else-if="error"><h1>We couldn't open this order</h1><p>{{error}}</p><button @click="router.push('/')">Back to events</button></section><section v-else-if="review"><h1>Payment received</h1><p>We're checking ticket availability before issuing your tickets. You do not need to pay again.</p></section><template v-else-if="paid"><section><h1>You're in.</h1><p>Payment confirmed. Your tickets are ready.</p></section><section v-for="group in groups" :key="group.event_title"><h2>{{group.event_title}}</h2><article v-for="item in group.items" :key="item.id"><div v-for="ticket in item.tickets" :key="ticket.public_id"><strong>{{item.ticket_name}}</strong><span>Ticket {{ticket.public_id}}</span><span v-if="ticket.admit_count>1">Admits {{ticket.admit_count}}</span><QrcodeVue :value="ticket.token" :size="112" level="M" render-as="svg"/></div></article></section></template><section v-else><h1>Payment is still confirming</h1><button @click="load">Check again</button></section></main></template><style scoped>main{min-height:100vh;padding:60px 18px;background:var(--color-bg);color:var(--color-text)}section{max-width:760px;margin:0 auto 24px;padding:28px;border:1px solid var(--color-border);border-radius:16px;background:var(--color-surface)}article>div{display:flex;justify-content:space-between;align-items:center;padding:14px;border:1px solid var(--color-border);margin-top:12px}span{display:block;color:var(--color-muted)}button{min-height:46px;padding:0 20px;border:0;border-radius:999px;background:var(--color-accent);color:#fff}</style>
